      stadtwerkMauerSalesWorkbenchBriefingStatus: 5 * 60 * 1000, // 5 min
      stadtwerkMauerWorkbenchLandingStatus: 5 * 60 * 1000, // 5 min
      stadtwerkMauerWorkbenchSelectedTargetStatus: 5 * 60 * 1000, // 5 min
