      if (!isProvided(params.billingStatus) || !isProvided(params.settlementStatus))
        addGap('billing_settlement_status');
      if (!isProvided(params.roleOwner)) addGap('role_owner');
      if (!isProvided(params.deadline)) addGap('deadline');
